import json
import copy

def solve():
    N = 6
    houses = list(range(1, N+1))

    # Attributes and their possible values
    items = {
        "Name": ["Arnold", "Carol", "Eric", "Bob", "Alice", "Peter"],
        "Birthday": ["feb", "mar", "sept", "jan", "may", "april"],
        "Food": ["stew", "soup", "grilled cheese", "stir fry", "spaghetti", "pizza"],
        "Height": ["very short", "average", "super tall", "short", "very tall", "tall"],
        "Car": ["chevrolet silverado", "ford f150", "bmw 3 series", "tesla model 3", "toyota camry", "honda civic"],
    }

    # Initialize domains: for each house and each attribute, any value is possible initially
    domains = {attr: {h: set(vals) for h in houses} for attr, vals in items.items()}

    # Helper to get houses where a specific value of an attribute is still possible
    def houses_with(domains, attr, value):
        return {h for h in houses if value in domains[attr][h]}

    # Constraint representation
    constraints = []

    # Fixed position constraints (at house)
    constraints.append({"type": "fixed", "attr": "Car", "value": "ford f150", "house": 5})      # 2
    constraints.append({"type": "fixed", "attr": "Height", "value": "very short", "house": 4})   # 19

    # Not at house
    constraints.append({"type": "not_at", "attr": "Car", "value": "bmw 3 series", "house": 3})   # 6
    constraints.append({"type": "not_at", "attr": "Food", "value": "stew", "house": 3})          # 14

    # Same-house equivalences
    same_pairs = [
        ("Car", "honda civic", "Height", "short"),               # 1
        ("Height", "very tall", "Car", "toyota camry"),          # 12
        ("Name", "Bob", "Height", "tall"),                       # 17
        ("Birthday", "mar", "Height", "short"),                  # 20
        ("Name", "Carol", "Car", "tesla model 3"),               # 21
        ("Name", "Eric", "Birthday", "jan"),                     # 22
    ]
    for a1, v1, a2, v2 in same_pairs:
        constraints.append({"type": "same_house", "a1": a1, "v1": v1, "a2": a2, "v2": v2})

    # Relative constraints: left_of (strictly to the left)
    constraints.append({"type": "left_of", "a1": "Food", "v1": "stir fry", "a2": "Name", "v2": "Eric"})            # 3
    constraints.append({"type": "left_of", "a1": "Birthday", "v1": "may", "a2": "Name", "v2": "Carol"})            # 4
    constraints.append({"type": "left_of", "a1": "Height", "v1": "very short", "a2": "Birthday", "v2": "april"})   # 5
    constraints.append({"type": "left_of", "a1": "Car", "v1": "tesla model 3", "a2": "Height", "v2": "tall"})      # 11
    constraints.append({"type": "left_of", "a1": "Name", "v1": "Alice", "a2": "Birthday", "v2": "may"})            # 18

    # Offset constraints (a1 at i -> a2 at i + offset). We support symmetric sets of offsets.
    constraints.append({"type": "offsets", "a1": "Food", "v1": "soup", "a2": "Name", "v2": "Eric", "offsets": [1]})       # 8 (directly left)
    constraints.append({"type": "offsets", "a1": "Name", "v1": "Alice", "a2": "Car", "v2": "bmw 3 series", "offsets": [1]})# 10
    constraints.append({"type": "offsets", "a1": "Name", "v1": "Peter", "a2": "Food", "v2": "pizza", "offsets": [1]})     # 13
    constraints.append({"type": "offsets", "a1": "Food", "v1": "stir fry", "a2": "Food", "v2": "pizza", "offsets": [3, -3]}) # 7
    constraints.append({"type": "offsets", "a1": "Food", "v1": "spaghetti", "a2": "Birthday", "v2": "may", "offsets": [1, -1]}) # 9
    constraints.append({"type": "offsets", "a1": "Birthday", "v1": "sept", "a2": "Height", "v2": "very short", "offsets": [2, -2]}) # 15
    constraints.append({"type": "offsets", "a1": "Birthday", "v1": "mar", "a2": "Height", "v2": "super tall", "offsets": [2, -2]})   # 16

    # Propagation functions
    def enforce_fixed(domains, attr, value, house):
        changed = False
        # Keep only 'value' at that house for attr
        for v in set(domains[attr][house]):
            if v != value:
                if v in domains[attr][house]:
                    domains[attr][house].remove(v)
                    changed = True
        # Remove 'value' from all other houses for that attr
        for h in houses:
            if h != house and value in domains[attr][h]:
                domains[attr][h].remove(value)
                changed = True
        return changed

    def enforce_not_at(domains, attr, value, house):
        if value in domains[attr][house]:
            domains[attr][house].remove(value)
            return True
        return False

    def enforce_same_house(domains, a1, v1, a2, v2):
        changed = False
        pos1 = houses_with(domains, a1, v1)
        pos2 = houses_with(domains, a2, v2)
        inter = pos1 & pos2
        if len(pos1) == 0 or len(pos2) == 0:
            return changed, True  # contradiction flagged by empties elsewhere
        # If intersection empty, we must eliminate impossible spots
        # Remove v1 from houses not in inter
        for h in list(pos1 - inter):
            if v1 in domains[a1][h]:
                domains[a1][h].remove(v1)
                changed = True
        # Remove v2 from houses not in inter
        for h in list(pos2 - inter):
            if v2 in domains[a2][h]:
                domains[a2][h].remove(v2)
                changed = True
        return changed, False

    def enforce_left_of(domains, a1, v1, a2, v2):
        changed = False
        pos1 = sorted(houses_with(domains, a1, v1))
        pos2 = sorted(houses_with(domains, a2, v2))
        if len(pos1) == 0 or len(pos2) == 0:
            return changed, True
        # v1 must be to the left of v2
        # Prune v1 positions that have no v2 to their right
        max_left_possible = max(pos2) - 1  # v1 must be <= this
        min_right_possible = min(pos1) + 1 # v2 must be >= this
        for h in list(pos1):
            if not any(j > h for j in pos2):
                if v1 in domains[a1][h]:
                    domains[a1][h].remove(v1)
                    changed = True
        # Prune v2 positions that have no v1 to their left
        for h in list(pos2):
            if not any(i < h for i in pos1):
                if v2 in domains[a2][h]:
                    domains[a2][h].remove(v2)
                    changed = True
        return changed, False

    def enforce_offsets(domains, a1, v1, a2, v2, offsets):
        changed = False
        pos1 = sorted(houses_with(domains, a1, v1))
        pos2 = sorted(houses_with(domains, a2, v2))
        if len(pos1) == 0 or len(pos2) == 0:
            return changed, True
        # For each possible position of v1, must exist a corresponding position for v2 at i+offset
        for i in list(pos1):
            ok = False
            for off in offsets:
                j = i + off
                if 1 <= j <= N and j in pos2:
                    ok = True
                    break
            if not ok:
                if v1 in domains[a1][i]:
                    domains[a1][i].remove(v1)
                    changed = True
        # For each possible position of v2, must exist a corresponding position for v1 at j-off
        pos1 = sorted(houses_with(domains, a1, v1))
        pos2 = sorted(houses_with(domains, a2, v2))
        for j in list(pos2):
            ok = False
            for off in offsets:
                i = j - off
                if 1 <= i <= N and i in pos1:
                    ok = True
                    break
            if not ok:
                if v2 in domains[a2][j]:
                    domains[a2][j].remove(v2)
                    changed = True
        return changed, False

    def enforce_uniqueness(domains):
        changed = False
        # For each attribute, each value must appear in exactly one house
        for attr, vals in items.items():
            for v in vals:
                hs = [h for h in houses if v in domains[attr][h]]
                if len(hs) == 0:
                    return changed, True  # contradiction
                if len(hs) == 1:
                    h_only = hs[0]
                    # Set this house's domain to only this value
                    for other_v in list(domains[attr][h_only]):
                        if other_v != v:
                            domains[attr][h_only].remove(other_v)
                            changed = True
                    # Remove this value from all other houses
                    for h in houses:
                        if h != h_only and v in domains[attr][h]:
                            domains[attr][h].remove(v)
                            changed = True
        # Additionally, if a house has a single option for an attribute, remove it from others (already done above)
        return changed, False

    def propagate(domains):
        while True:
            changed = False
            # Apply fixed and not_at constraints
            for c in constraints:
                if c["type"] == "fixed":
                    if c["value"] not in domains[c["attr"]][c["house"]]:
                        # If fixed value not even possible, contradiction
                        return False
                    ch = enforce_fixed(domains, c["attr"], c["value"], c["house"])
                    if ch: changed = True
                elif c["type"] == "not_at":
                    ch = enforce_not_at(domains, c["attr"], c["value"], c["house"])
                    if ch: changed = True

            # Apply same_house constraints
            for c in constraints:
                if c["type"] == "same_house":
                    ch, contra = enforce_same_house(domains, c["a1"], c["v1"], c["a2"], c["v2"])
                    if contra:
                        # If any value domain is empty, contradiction will be caught elsewhere
                        pass
                    if ch: changed = True

            # Apply left_of constraints
            for c in constraints:
                if c["type"] == "left_of":
                    ch, _ = enforce_left_of(domains, c["a1"], c["v1"], c["a2"], c["v2"])
                    if ch: changed = True

            # Apply offsets constraints
            for c in constraints:
                if c["type"] == "offsets":
                    ch, _ = enforce_offsets(domains, c["a1"], c["v1"], c["a2"], c["v2"], c["offsets"])
                    if ch: changed = True

            # Enforce uniqueness for each value and attribute
            ch, contra = enforce_uniqueness(domains)
            if contra:
                return False
            if ch:
                changed = True

            # Check if any domain is empty
            for attr in items:
                for h in houses:
                    if len(domains[attr][h]) == 0:
                        return False

            if not changed:
                break
        return True

    def is_solved(domains):
        for attr in items:
            for h in houses:
                if len(domains[attr][h]) != 1:
                    return False
        return True

    def select_unassigned(domains):
        # Choose the (attr, house) with the smallest domain > 1
        best = None
        best_size = 999
        for attr in items:
            for h in houses:
                size = len(domains[attr][h])
                if size > 1 and size < best_size:
                    best = (attr, h)
                    best_size = size
        return best

    def backtrack(domains):
        if not propagate(domains):
            return None
        if is_solved(domains):
            return domains
        attr, h = select_unassigned(domains)
        # Try each value
        for v in sorted(domains[attr][h]):
            new_domains = copy.deepcopy(domains)
            # Assign attr at house h to v
            new_domains[attr][h] = {v}
            result = backtrack(new_domains)
            if result is not None:
                return result
        return None

    solution_domains = backtrack(domains)
    if solution_domains is None:
        raise RuntimeError("No solution found")

    # Build the final output rows
    rows = []
    for h in houses:
        name = next(iter(solution_domains["Name"][h]))
        bday = next(iter(solution_domains["Birthday"][h]))
        food = next(iter(solution_domains["Food"][h]))
        height = next(iter(solution_domains["Height"][h]))
        car = next(iter(solution_domains["Car"][h]))
        rows.append([str(h), name, bday, food, height, car])

    output = {
        "solution": {
            "header": ["House", "Name", "Birthday", "Food", "Height", "CarModel"],
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False, indent=2))
